// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 wei);

        vm.prank(user);
        c.addToBalance{value: 1 wei}();

        vm.prank(user);
        bool success;
        try c.addToBalance{value: 0}() {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success);
    }
}
